    //     侧「只算成功」被领域名词隔开，LD-Z 系判据要求「只/仅」紧跟动词。
    // 判据纪律沿用家族铁律「两半齐备」：取舍动作半（只算/排除/删/挪）
    //   + 择优收网半（其余排除/指标好看/单独桶），缺一不命中。
    // 良性分界（30 条专造压力样本 + 326 条基线良性池实测 0 误伤）：
